-- PatchGraph PostgreSQL schema for the capstone MVP
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, display_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (project_id uuid REFERENCES projects ON DELETE CASCADE, user_id uuid REFERENCES users ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('viewer','analyst','approver','admin')), PRIMARY KEY(project_id,user_id));
CREATE TABLE applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, name text NOT NULL, criticality smallint NOT NULL CHECK (criticality BETWEEN 1 AND 5), UNIQUE(project_id,name));
CREATE TABLE services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES applications ON DELETE CASCADE, name text NOT NULL, owner_email text, UNIQUE(application_id,name));
CREATE TABLE environments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, name text NOT NULL, production boolean NOT NULL DEFAULT false, max_downtime_minutes integer CHECK (max_downtime_minutes >= 0), UNIQUE(project_id,name));
CREATE TABLE assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, environment_id uuid REFERENCES environments, external_key text NOT NULL, kind text NOT NULL, criticality smallint CHECK (criticality BETWEEN 1 AND 5), metadata jsonb NOT NULL DEFAULT '{}', UNIQUE(project_id,external_key));
CREATE TABLE packages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ecosystem text NOT NULL, normalized_name text NOT NULL, purl text, UNIQUE(ecosystem,normalized_name));
CREATE TABLE package_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), package_id uuid NOT NULL REFERENCES packages ON DELETE CASCADE, version text NOT NULL, normalized_version text, UNIQUE(package_id,version));
CREATE TABLE imports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, kind text NOT NULL CHECK (kind IN ('cyclonedx','spdx','vex')), status text NOT NULL, source_name text NOT NULL, content_sha256 char(64) NOT NULL, object_key text NOT NULL, parser_version text NOT NULL, errors jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,content_sha256,kind));
CREATE TABLE dependencies (id bigserial PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, parent_version_id uuid NOT NULL REFERENCES package_versions, child_version_id uuid NOT NULL REFERENCES package_versions, scope text, optional boolean NOT NULL DEFAULT false, import_id uuid NOT NULL REFERENCES imports ON DELETE CASCADE, UNIQUE(import_id,parent_version_id,child_version_id,scope));
CREATE TABLE service_components (service_id uuid REFERENCES services ON DELETE CASCADE, environment_id uuid REFERENCES environments ON DELETE CASCADE, package_version_id uuid REFERENCES package_versions ON DELETE CASCADE, import_id uuid REFERENCES imports ON DELETE CASCADE, direct boolean NOT NULL DEFAULT false, PRIMARY KEY(service_id,environment_id,package_version_id,import_id));
CREATE TABLE deployments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), service_id uuid NOT NULL REFERENCES services ON DELETE CASCADE, asset_id uuid NOT NULL REFERENCES assets ON DELETE CASCADE, deployed_at timestamptz, release_ref text, UNIQUE(service_id,asset_id,release_ref));
CREATE TABLE vulnerabilities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), canonical_id text NOT NULL UNIQUE, published_at timestamptz, modified_at timestamptz, summary text);
CREATE TABLE advisories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vulnerability_id uuid NOT NULL REFERENCES vulnerabilities ON DELETE CASCADE, source text NOT NULL, external_id text NOT NULL, source_url text, fetched_at timestamptz NOT NULL, content_sha256 char(64) NOT NULL, raw_object_key text, payload jsonb NOT NULL, UNIQUE(source,external_id,content_sha256));
CREATE TABLE affected_ranges (id bigserial PRIMARY KEY, advisory_id uuid NOT NULL REFERENCES advisories ON DELETE CASCADE, package_id uuid NOT NULL REFERENCES packages ON DELETE CASCADE, range_type text NOT NULL, introduced text, fixed text, last_affected text);
CREATE TABLE exploit_evidence (vulnerability_id uuid REFERENCES vulnerabilities ON DELETE CASCADE, observed_on date NOT NULL, source text NOT NULL, epss double precision CHECK (epss BETWEEN 0 AND 1), percentile double precision CHECK (percentile BETWEEN 0 AND 1), known_exploited boolean, evidence jsonb NOT NULL DEFAULT '{}', PRIMARY KEY(vulnerability_id,observed_on,source));
CREATE TABLE vex_statements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, import_id uuid NOT NULL REFERENCES imports ON DELETE CASCADE, vulnerability_id uuid REFERENCES vulnerabilities, package_version_id uuid REFERENCES package_versions, status text NOT NULL CHECK (status IN ('affected','not_affected','fixed','under_investigation')), justification text, action_statement text, UNIQUE(import_id,vulnerability_id,package_version_id));
CREATE TABLE evidence_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), source_cutoffs jsonb NOT NULL, manifest_sha256 char(64) NOT NULL UNIQUE);
CREATE TABLE findings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, vulnerability_id uuid NOT NULL REFERENCES vulnerabilities, package_version_id uuid NOT NULL REFERENCES package_versions, service_id uuid REFERENCES services, environment_id uuid REFERENCES environments, applicability text NOT NULL, status text NOT NULL DEFAULT 'open', UNIQUE(project_id,vulnerability_id,package_version_id,service_id,environment_id));
CREATE TABLE risk_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, snapshot_id uuid NOT NULL REFERENCES evidence_snapshots, model_version text NOT NULL, config jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE finding_scores (risk_run_id uuid REFERENCES risk_runs ON DELETE CASCADE, finding_id uuid REFERENCES findings ON DELETE CASCADE, probability double precision CHECK (probability BETWEEN 0 AND 1), baseline_score double precision NOT NULL, final_score double precision NOT NULL, uncertainty double precision CHECK (uncertainty BETWEEN 0 AND 1), factors jsonb NOT NULL, PRIMARY KEY(risk_run_id,finding_id));
CREATE TABLE planning_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, risk_run_id uuid NOT NULL REFERENCES risk_runs, status text NOT NULL, objective_value double precision, best_bound double precision, runtime_ms integer, constraints jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE remediation_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), planning_run_id uuid NOT NULL REFERENCES planning_runs ON DELETE CASCADE, package_id uuid REFERENCES packages, from_version text, to_version text, action_type text NOT NULL, selected boolean NOT NULL, effort_hours double precision CHECK (effort_hours >= 0), downtime_minutes integer CHECK (downtime_minutes >= 0), compatibility_risk double precision CHECK (compatibility_risk BETWEEN 0 AND 1), risk_removed double precision NOT NULL, rationale jsonb NOT NULL);
CREATE TABLE plan_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), planning_run_id uuid NOT NULL REFERENCES planning_runs ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users, decision text NOT NULL CHECK (decision IN ('approved','rejected','needs_changes')), reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id bigserial PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, actor_id uuid REFERENCES users, action text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, request_id text, before_state jsonb, after_state jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_assets_project_environment ON assets(project_id,environment_id);
CREATE INDEX idx_dependencies_parent ON dependencies(parent_version_id);
CREATE INDEX idx_dependencies_child ON dependencies(child_version_id);
CREATE INDEX idx_service_components_version ON service_components(package_version_id);
CREATE INDEX idx_findings_project_status ON findings(project_id,status);
CREATE INDEX idx_findings_vulnerability ON findings(vulnerability_id);
CREATE INDEX idx_scores_run_rank ON finding_scores(risk_run_id,final_score DESC);
CREATE INDEX idx_advisories_vulnerability_source ON advisories(vulnerability_id,source);
CREATE INDEX idx_advisories_payload_gin ON advisories USING gin(payload);
CREATE INDEX idx_audit_project_created ON audit_logs(project_id,created_at DESC);
